  ) v(id, versao, nome_atual, nome_novo, sigla) LOOP
    UPDATE public.emenda_beneficiarios b
       SET sigla = r.sigla,
           nome = COALESCE(r.nome_novo, b.nome),
           outros_nomes = CASE WHEN r.nome_novo IS NULL THEN b.outros_nomes
                               ELSE ARRAY(SELECT DISTINCT x FROM unnest(b.outros_nomes || ARRAY[b.nome::TEXT]) x WHERE x <> r.nome_novo) END,
           versao = b.versao + 1, atualizado_por_nome = 'Siglas dos beneficiários (CGLIC)', atualizado_em = NOW()
     WHERE b.id = r.id AND b.versao = r.versao AND b.nome = r.nome_atual AND NULLIF(btrim(COALESCE(b.sigla, '')), '') IS NULL;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n <> 1 THEN
      RAISE EXCEPTION 'Cadastro % (%) mudou desde a conferência; refazer a lista.', r.nome_atual, r.id;
    END IF;
  END LOOP;
END $$;
